{"code": "# Check file headers to identify the actual image format
import os
import binascii

train_path = 'data_small/chest-xray-pneumonia/chest_xray/train'

for class_name in ['PNEUMONIA', 'NORMAL']:
    class_path = os.path.join(train_path, class_name)
    files = os.listdir(class_path)
    for f in files[:3]:
        img_path = os.path.join(class_path, f)
        try:
            with open(img_path, 'rb') as file:
                header = file.read(8)
                hex_header = binascii.hexlify(header).decode('latin-1')
                print(f"{f}: {hex_header}")
        except Exception as e:
            print(f"Error reading {f}: {e}")"}

